content:
:root {
  --primary-color: #6f4e37;
  --secondary-color: #d2b48c;
  --accent-color: #c08552;
  --bg-color: #fdfbf7;
  --card-bg: #ffffff;
  --text-color: #333333;
  --text-light: #666666;
  --border-radius: 12px;
  --transition: all 0.3s ease;
  --font-base: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  --breakpoint-md: 768px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-base);
  background-color: var(--bg-color);
  color: var(--text-color);
  line-height: 1.6;
}

.cafe-app {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

/* ヒーローセクション */
.hero-section {
  position: relative;
  height: 70vh;
  min-height: 450px;
  background: linear-gradient(rgba(0, 0, 0, 0.4), rgba(0, 0, 0, 0.4)), url('https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1200&q=80') center/cover no-repeat;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  color: #ffffff;
  padding: 0 20px;
}

.hero-title {
  font-size: 3rem;
  font-weight: 700;
  margin-bottom: 1rem;
  letter-spacing: 0.05em;
  text-shadow: 0 2px 4px rgba(0,0,0,0.3);
}

.hero-subtitle {
  font-size: 1.2rem;
  max-width: 600px;
  margin-bottom: 2rem;
  font-weight: 300;
  text-shadow: 0 1px 2px rgba(0,0,0,0.3);
}

/* ボタン */
.btn {
  display: inline-block;
  background-color: var(--primary-color);
  color: #ffffff;
  padding: 12px 28px;
  border-radius: 30px;
  text-decoration: none;
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: var(--transition);
  box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}

.btn:hover {
  background-color: var(--accent-color);
  transform: translateY(-2px);
  box-shadow: 0 6px 8px rgba(0,0,0,0.15);
}

/* 共通セクションタイトル */
.section-title {
  font-size: 2.2rem;
  text-align: center;
  margin-bottom: 3rem;
  color: var(--primary-color);
  position: relative;
  font-weight: 700;
}

.section-title::after {
  content: '';
  display: block;
  width: 60px;
  height: 3px;
  background-color: var(--secondary-color);
  margin: 10px auto 0;
  border-radius: 2px;
}

/* メニューセクション */
.menu-section {
  padding: 80px 20px;
  max-width: 1200px;
  margin: 0 auto;
  width: 100%;
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 30px;
}

.menu-card {
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  overflow: hidden;
  box-shadow: 0 4px 15px rgba(0,0,0,0.05);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.menu-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 25px rgba(0,0,0,0.1);
}

.menu-img {
  width: 100%;
  height: 200px;
  object-fit: cover;
}

.menu-info {
  padding: 20px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.tag {
  display: inline-block;
  background-color: var(--secondary-color);
  color: var(--primary-color);
  font-size: 0.75rem;
  padding: 4px 10px;
  border-radius: 20px;
  font-weight: 600;
  margin-bottom: 10px;
  align-self: flex-start;
}

/* アクセスセクション */
.access-section {
  padding: 80px 20px;
  background-color: #f5efe6;
}

.access-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}

.access-info {
  background-color: var(--card-bg);
  padding: 40px;
  border-radius: var(--border-radius);
  box-shadow: 0 4px 15px rgba(0,0,0,0.05);
}

.access-info p {
  margin-bottom: 15px;
  font-size: 1.05rem;
  color: var(--text-light);
}

.access-info strong {
  color: var(--primary-color);
  display: inline-block;
  width: 100px;
}

.map-mock {
  width: 100%;
  height: 350px;
  background-color: #e5dcc5;
  border-radius: var(--border-radius);
  display: flex;
  justify-content: center;
  align-items: center;
  color: var(--primary-color);
  font-weight: 600;
  box-shadow: 0 4px 15px rgba(0,0,0,0.05);
  border: 2px dashed var(--secondary-color);
}

/* フッター */
.footer {
  background-color: #2c221e;
  color: #ffffff;
  text-align: center;
  padding: 40px 20px;
  margin-top: auto;
  font-size: 0.9rem;
  font-weight: 300;
}

/* レスポンシブ対応 */
@media (max-width: 768px) {
  .hero-title {
    font-size: 2.2rem;
  }

  .hero-subtitle {
    font-size: 1rem;
  }

  .access-grid {
    grid-template-columns: 1fr;
  }

  .section-title {
    font-size: 1.8rem;
    margin-bottom: 2rem;
  }
}

/**
 * メニューのカテゴリ一覧
 */
export const CATEGORIES = ['coffee', 'food', 'sweets'] as const;

/**
 * メニューのカテゴリ型
 */
export type Category = typeof CATEGORIES[number];

/**
 * メニューアイテムの型定義
 */
export interface MenuItem {
  /** 一意の識別子 */
  id: string;
  /** メニュー名 */
  name: string;
  /** カテゴリ */
  category: Category;
  /** 価格 (円) */
  price: number;
  /** 説明文 */
  description: string;
  /** おすすめフラグ */
  isRecommended: boolean;
  /** 画像URL */
  image: string;
  /** カロリー情報 (オプショナル) */
  calories?: number;
}

/**
 * アクセス・店舗情報の型定義
 */
export interface AccessInfo {
  /** 住所 */
  address: string;
  /** 営業時間 */
  hours: string;
  /** 定休日 */
  closed: string;
  /** 最寄り駅 */
  station: string;
  /** 電話番号 */
  phone: string;
  /** 備考 (オプショナル) */
  notes?: string;
}

import { FC } from 'react';

interface HeroProps {
  onExploreClick?: () => void;
}

export const Hero: FC<HeroProps> = ({ onExploreClick }) => {
  const handleClick = () => {
    if (onExploreClick) {
      onExploreClick();
    } else {
      const el = document.getElementById('menu-section');
      if (el) {
        el.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  return (
    <section className="hero-section">
      <h1 className="hero-title">Aroma Garden Cafe</h1>
      <p className="hero-subtitle">
        心安らぐ空間と、こだわりの自家焙煎コーヒー。至福のひとときをお届けします。
      </p>
      <button 
        className="btn" 
        onClick={handleClick}
        aria-label="メニューセクションへ移動する"
      >
        メニューを見る
      </button>
    </section>
  );
};

export default Hero;

import { FC, useState } from 'react';
import { MenuItem } from '../types';

interface MenuSectionProps {
  items?: MenuItem[];
}

export const MenuSection: FC<MenuSectionProps> = ({ items = [] }) => {
  const [activeCategory, setActiveCategory] = useState<'all' | 'coffee' | 'food' | 'sweets'>('all');
  const [imageErrors, setImageErrors] = useState<Record<string, boolean>>({});

  const filteredItems = items.filter(item => {
    if (activeCategory === 'all') return true;
    return item.category === activeCategory;
  });

  const handleImageError = (id: string) => {
    setImageErrors(prev => ({ ...prev, [id]: true }));
  };

  const categories = [
    { key: 'all', label: 'すべて' },
    { key: 'coffee', label: 'コーヒー' },
    { key: 'food', label: 'フード' },
    { key: 'sweets', label: 'スイーツ' },
  ] as const;

  return (
    <section className="menu-section" id="menu-section">
      <h2 className="section-title">Our Menu</h2>

      <div style={{ display: 'flex', justifyContent: 'center', gap: '10px', marginBottom: '40px', flexWrap: 'wrap' }}>
        {categories.map(cat => (
          <button 
            key={cat.key}
            className="btn"
            style={{ 
              backgroundColor: activeCategory === cat.key ? 'var(--accent-color)' : 'var(--primary-color)',
              padding: '8px 20px',
              fontSize: '0.9rem'
            }}
            onClick={() => setActiveCategory(cat.key)}
          >
            {cat.label}
          </button>
        ))}
      </div>

      <div className="menu-grid">
        {filteredItems.map(item => {
          const imgSrc = imageErrors[item.id] 
            ? 'https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=600&q=80' 
            : item.image;

          return (
            <div className="menu-card" key={item.id}>
              <img 
                src={imgSrc} 
                alt={item.name} 
                className="menu-img" 
                onError={() => handleImageError(item.id)}
              />
              <div className="menu-info">
                {item.isRecommended && <span className="tag">おすすめ</span>}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
                  <h3 style={{ fontSize: '1.2rem', fontWeight: 600, color: 'var(--text-color)' }}>{item.name}</h3>
                  <span style={{ fontSize: '1.1rem', fontWeight: 700, color: 'var(--primary-color)' }}>¥{item.price.toLocaleString()}</span>
                </div>
                <p style={{ color: 'var(--text-light)', fontSize: '0.95rem' }}>{item.description}</p>
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
};

export default MenuSection;

import { FC } from 'react';
import { AccessInfo } from '../types';

interface AccessSectionProps {
  access: AccessInfo;
}

export const AccessSection: FC<AccessSectionProps> = ({ access }) => {
  const mapSearchUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(access.address)}`;

  return (
    <section className="access-section">
      <h2 className="section-title">Access & Info</h2>
      <div className="access-grid">
        <div className="access-info">
          <p><strong>住所:</strong> {access.address}</p>
          <p><strong>営業時間:</strong> {access.hours}</p>
          <p><strong>定休日:</strong> {access.closed}</p>
          <p><strong>最寄り駅:</strong> {access.station}</p>
          <p><strong>電話番号:</strong> <a href={`tel:${access.phone.replace(/-/g, '')}`} style={{ color: 'var(--primary-color)', textDecoration: 'underline' }}>{access.phone}</a></p>
        </div>
        <a 
          href={mapSearchUrl} 
          target="_blank" 
          rel="noopener noreferrer" 
          className="map-mock"
          style={{ textDecoration: 'none', cursor: 'pointer', display: 'flex', flexDirection: 'column', gap: '8px' }}
        >
          <span>Googleマップで見る</span>
          <span style={{ fontSize: '0.85rem', fontWeight: 'normal' }}>(外部サイトが開きます)</span>
        </a>
      </div>
    </section>
  );
};

export default AccessSection;

import { useState } from 'react';
import Hero from './components/Hero';
import MenuSection from './components/MenuSection';
import AccessSection from './components/AccessSection';
import { MenuItem, AccessInfo } from './types';
import { initialMenuItems, accessData } from './data/mockData';
import { useSmoothScroll } from './hooks/useSmoothScroll';

export default function App() {
  const [menuItems] = useState<MenuItem[]>(initialMenuItems);
  const [accessInfo] = useState<AccessInfo>(accessData);
  const { scrollToSection } = useSmoothScroll();

  const handleExplore = () => {
    scrollToSection('menu-section');
  };

  return (
    <div className="cafe-app">
      <Hero onExploreClick={handleExplore} />
      <MenuSection items={menuItems} />
      <AccessSection access={accessInfo} />
      <footer className="footer">
        <p>&copy; 2025 Aroma Garden Cafe. All Rights Reserved.</p>
      </footer>
    </div>
  );
}

export const useSmoothScroll = () => {
  const scrollToSection = (elementId: string) => {
    const el = document.getElementById(elementId);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return { scrollToSection };
};
